import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"聊天室","description":"聊天室的各種功能介紹。包含私訊、頻道及展示物品等。","frontmatter":{"title":"聊天室","description":"聊天室的各種功能介紹。包含私訊、頻道及展示物品等。"},"headers":[],"relativePath":"feature/chat/index.md","filePath":"feature/chat.md"}'),t={name:"feature/chat/index.md"};function c(d,l,r,u,h,s){return i(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="聊天室" tabindex="-1">聊天室 <a class="header-anchor" href="#聊天室" aria-label="Permalink to &quot;聊天室&quot;">​</a></h1><h2 id="密語指令" tabindex="-1">密語指令 <a class="header-anchor" href="#密語指令" aria-label="Permalink to &quot;密語指令&quot;">​</a></h2><p>用來發送密語給別人，可以跨伺服傳送</p><ul><li><code>/tell &lt;玩家ID&gt; &lt;文字&gt;</code><b>發送密語給他人</b>(/m , /msg 也是同樣效果)</li><li><code>/r &lt;文字&gt;</code><b>密語回覆上一個發送你密語的人</b></li></ul><h2 id="禁言指令" tabindex="-1">禁言指令 <a class="header-anchor" href="#禁言指令" aria-label="Permalink to &quot;禁言指令&quot;">​</a></h2><p>用來禁言玩家，阻擋你不想要看到的訊息<br> 禁言範圍包含公頻(遊戲內及DC同步訊息)及密語</p><ul><li><code>/ignore &lt;玩家ID&gt;</code><b>將指定玩家禁言</b><ul><li>重新輸入即可解除禁言</li></ul></li><li><code>/ignore</code><b>查看被你禁言的玩家</b><ul><li>會在聊天欄列出列表</li></ul></li></ul><h2 id="頻道系統" tabindex="-1">頻道系統 <a class="header-anchor" href="#頻道系統" aria-label="Permalink to &quot;頻道系統&quot;">​</a></h2><p>用來管理接收/發送訊息的指令</p><ul><li><code>/c</code><b>開啟頻道列表</b><ul><li><p>用來管理接收哪些頻道的訊息<br><img src="https://i.imgur.com/gv3F8oJ.png" style="width:60%;"></p><ul><li>移動到按鍵上可查看說明</li></ul></li></ul></li><li><code>/ch chat &lt;頻道代號&gt;</code><b>設定發話頻道</b><ul><li>頻道代號可在指令<code>/c</code>的介面中 將滑鼠移到頻道列表上查詢</li><li>部分同步頻道不開放遊戲內發送訊息，詳見<a href="/discord/text_channel/">Discord文字頻道</a></li></ul></li></ul><h2 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to &quot;其他功能&quot;">​</a></h2><ul><li>在遊戲內tag玩家(對方須綁定Discord) <ul><li>使用方式：<code>@&lt;玩家ID&gt;</code></li></ul></li><li>在遊戲內傳送伺服Discord表情符號 <ul><li>使用方式：<code>:&lt;表情符號ID&gt;:</code></li></ul></li><li>調整上下線訊息顯示方式 <ul><li>使用方式：<code>/lm</code><br><img src="https://i.imgur.com/U7xqzwt.png" style="width:80%;"></li></ul></li><li>將訊息傳送至<a href="/discord/customer_service/">Discord客服系統</a><ul><li>使用方式：<code>/mcs &lt;訊息內容&gt;</code></li><li>須將遊戲帳號<a href="/discord/">綁定Discord帳號</a></li><li>如尚未建立客服頻道會立即開啟</li><li>訊息會在遊戲內及Discord中同步 <img src="https://i.imgur.com/iyECKjU.png" style="width:80%;"></li></ul></li></ul><h2 id="遊戲內寄信" tabindex="-1">遊戲內寄信 <a class="header-anchor" href="#遊戲內寄信" aria-label="Permalink to &quot;遊戲內寄信&quot;">​</a></h2><ul><li>在遊戲內寄信給其他玩家，對方會在上線或切換分流時收到信件 <ul><li>使用方式：<code>/mail send &lt;玩家ID&gt; &lt;內容&gt;</code></li></ul></li></ul><h2 id="展示物品-item" tabindex="-1">展示物品<code>[item]</code> <a class="header-anchor" href="#展示物品-item" aria-label="Permalink to &quot;展示物品`[item]`&quot;">​</a></h2><p>用來在聊天室展示自己身上的物品<br><b>[]前後需與其他文字空格</b></p><ul><li><b>主手：</b><code>[item]</code> <code>[i]</code> <code>[inv]</code> <code>[hand]</code></li><li><b>副手：</b><code>[offhand]</code>(若打兩次展示主手的文字 後面的會自動轉換為副手)</li><li><b>頭盔：</b><code>[helmet]</code> <code>[head]</code> <code>[hat]</code></li><li><b>胸甲：</b><code>[chestplate]</code> <code>[body]</code></li><li><b>褲子：</b><code>[Leggings]</code> <code>[Legging]</code> <code>[leg]</code></li><li><b>鞋子：</b><code>[Boots]</code> <code>[boot]</code></li></ul><h2 id="名稱系統" tabindex="-1">名稱系統 <a class="header-anchor" href="#名稱系統" aria-label="Permalink to &quot;名稱系統&quot;">​</a></h2><p>用來管理遊戲內稱號、名字顏色及暱稱顯示</p><ul><li><code>/tg</code><b>開啟名稱系統介面</b><ul><li>稱號獲得方式請待日後公告</li><li>名字顏色及暱稱為<a href="/donate/">贊助回饋</a><br><img src="https://i.imgur.com/Fj88jws.png" style="width:60%;"><ul><li>移動到按鍵上可查看說明</li></ul></li></ul></li><li><code>/tguse</code><b>使用稱號兌換卷</b><ul><li>主手持稱號兌換卷輸入指令即可兌換</li></ul></li></ul>',20)])])}const m=e(t,[["render",c]]);export{b as __pageData,m as default};
